/* Openline Check service worker (generated by scripts/build_i18n.py).
   - Versioned assets (?v=), fonts, flags and icons: cache first (they never change for a given URL).
   - Pages: network first with a short timeout, falling back to the cached copy (works offline).
   - Everything else on this origin: stale-while-revalidate. */
var VERSION = "{{@v}}";
var CACHE = "ol-check-v" + VERSION;
var CORE = [
  "/style.min.css?v=" + VERSION,
  "/app.min.js?v=" + VERSION,
  "/devices.min.js?v=" + VERSION,
  "/fonts/inter-5.3.0/inter-latin-wght-normal.woff2"
];

self.addEventListener("install", function (event) {
  event.waitUntil(
    caches.open(CACHE).then(function (cache) { return cache.addAll(CORE); }).then(function () { return self.skipWaiting(); })
  );
});

self.addEventListener("activate", function (event) {
  event.waitUntil(
    caches.keys().then(function (keys) {
      return Promise.all(keys.filter(function (k) { return k.indexOf("ol-check-") === 0 && k !== CACHE; }).map(function (k) { return caches.delete(k); }));
    }).then(function () { return self.clients.claim(); })
  );
});

function isImmutable(url) {
  return url.searchParams.has("v") || /^\/(fonts|flags|icons)\//.test(url.pathname);
}

function pageKey(url) {
  // Cache pages without their query string so /fr/?q=pixel still works offline.
  return new Request(url.origin + url.pathname);
}

function networkFirst(request, key) {
  return caches.open(CACHE).then(function (cache) {
    var network = fetch(request).then(function (res) {
      if (res && res.ok) cache.put(key, res.clone());
      return res;
    });
    var timeout = new Promise(function (resolve) {
      setTimeout(function () { resolve(cache.match(key)); }, 2500);
    });
    return Promise.race([network.catch(function () { return cache.match(key); }), timeout]).then(function (res) {
      return res || network.catch(function () { return cache.match(key); }).then(function (r) {
        return r || cache.match(new Request(self.location.origin + "/"));
      });
    });
  });
}

function cacheFirst(request) {
  return caches.open(CACHE).then(function (cache) {
    return cache.match(request).then(function (hit) {
      return hit || fetch(request).then(function (res) {
        if (res && res.ok) cache.put(request, res.clone());
        return res;
      });
    });
  });
}

function staleWhileRevalidate(request) {
  return caches.open(CACHE).then(function (cache) {
    return cache.match(request).then(function (hit) {
      var network = fetch(request).then(function (res) {
        if (res && res.ok) cache.put(request, res.clone());
        return res;
      }).catch(function () { return hit; });
      return hit || network;
    });
  });
}

self.addEventListener("fetch", function (event) {
  var req = event.request;
  if (req.method !== "GET") return;
  var url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname === "/sw.js" || url.pathname === "/healthz") return;
  if (req.mode === "navigate" || (req.headers.get("accept") || "").indexOf("text/html") !== -1) {
    event.respondWith(networkFirst(req, pageKey(url)));
  } else if (isImmutable(url)) {
    event.respondWith(cacheFirst(req));
  } else {
    event.respondWith(staleWhileRevalidate(req));
  }
});
